11	// DefaultHostname is the domain name of the default GitHub instance.
12	const defaultHostname = "github.com"
13	
14	// Localhost is the domain name of a local GitHub instance.
15	const localhost = "github.localhost"
16	
17	// TenancyHost is the domain name of a tenancy GitHub instance.
18	const tenancyHost = "ghe.com"
19	
20	// Default returns the host name of the default GitHub instance.
21	func Default() string {
22		return defaultHostname
23	}
24	
25	// TenantName extracts the tenant name from tenancy host name and
26	// reports whether it found the tenant name.
27	func TenantName(h string) (string, bool) {
28		normalizedHostName := ghauth.NormalizeHostname(h)
29		return strings.CutSuffix(normalizedHostName, "."+tenancyHost)
30	}
