36	func HostnameValidator(hostname string) error {
37		if len(strings.TrimSpace(hostname)) < 1 {
38			return errors.New("a value is required")
39		}
40		if strings.ContainsRune(hostname, '/') || strings.ContainsRune(hostname, ':') {
41			return errors.New("invalid hostname")
42		}
43		return nil
44	}
45	
46	func GraphQLEndpoint(hostname string) string {
47		if isGarage(hostname) {
48			return fmt.Sprintf("https://%s/api/graphql", hostname)
49		}
50		if ghauth.IsEnterprise(hostname) {
51			return fmt.Sprintf("https://%s/api/graphql", hostname)
52		}
53		if strings.EqualFold(hostname, localhost) {
54			return fmt.Sprintf("http://api.%s/graphql", hostname)
55		}
56		return fmt.Sprintf("https://api.%s/graphql", hostname)
57	}
58	
59	func RESTPrefix(hostname string) string {
60		if isGarage(hostname) {
61			return fmt.Sprintf("https://%s/api/v3/", hostname)
62		}
63		if ghauth.IsEnterprise(hostname) {
64			return fmt.Sprintf("https://%s/api/v3/", hostname)
65		}
66		if strings.EqualFold(hostname, localhost) {
67			return fmt.Sprintf("http://api.%s/", hostname)
68		}
69		return fmt.Sprintf("https://api.%s/", hostname)
70	}
71	
72	func GistPrefix(hostname string) string {
73		prefix := "https://"
74		if strings.EqualFold(hostname, localhost) {
75			prefix = "http://"
76		}
77		return prefix + GistHost(hostname)
78	}
79	
80	func GistHost(hostname string) string {
81		if isGarage(hostname) {
82			return fmt.Sprintf("%s/gist/", hostname)
83		}
84		if ghauth.IsEnterprise(hostname) {
85			return fmt.Sprintf("%s/gist/", hostname)
86		}
87		if strings.EqualFold(hostname, localhost) {
88			return fmt.Sprintf("%s/gist/", hostname)
89		}
90		return fmt.Sprintf("gist.%s/", hostname)
91	}
92	
93	func HostPrefix(hostname string) string {
94		if strings.EqualFold(hostname, localhost) {
95			return fmt.Sprintf("http://%s/", hostname)
96		}
97		return fmt.Sprintf("https://%s/", hostname)
98	}
99	
100	func CategorizeHost(host string) string {
101		if host == defaultHostname {
102			return "github.com"
103		}
104	
105		if ghauth.IsEnterprise(host) {
106			return "ghes"
107		}
108	
109		if ghauth.IsTenancy(host) {
110			return "tenancy"
111		}
112	
113		return "uncategorized"
114	}
